package com.hbm.machine.oreslopper;
import com.hbm.item.battery.*;import com.hbm.item.fluid.FluidIdentifier;import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;
/** Exact eleven slots and source battery/identifier/raw/upgrades shift routing. */
public final class OreSlopperMenu extends AbstractContainerMenu {
 private final Container machine;private final ContainerData data;private final BlockPos pos;
 public OreSlopperMenu(int id,Inventory inv,RegistryFriendlyByteBuf buffer){this(id,inv,resolve(inv,buffer));}private OreSlopperMenu(int id,Inventory inv,ClientInit init){this(id,inv,init.inventory,new SimpleContainerData(8),init.pos);}private record ClientInit(Container inventory,BlockPos pos){}private static ClientInit resolve(Inventory inv,RegistryFriendlyByteBuf buffer){var p=buffer.readBlockPos();return new ClientInit(inv.player.level().getBlockEntity(p) instanceof OreSlopperBlockEntity machine?machine:new SimpleContainer(11),p);}
 public OreSlopperMenu(int id,Inventory inv,Container machine,ContainerData data,BlockPos pos){super(OreSlopperContent.MENU.get(),id);this.machine=machine;this.data=data;this.pos=pos;addSlot(new Slot(machine,0,8,72));addSlot(new Slot(machine,1,26,72));addSlot(new Slot(machine,2,71,27));for(int i=0;i<6;i++)addSlot(output(machine,3+i,134+i%2*18,18+i/2*18));addSlot(new Slot(machine,9,62,72));addSlot(new Slot(machine,10,80,72));for(int i=0;i<3;i++)for(int j=0;j<9;j++)addSlot(new Slot(inv,j+i*9+9,8+j*18,122+i*18));for(int j=0;j<9;j++)addSlot(new Slot(inv,j,8+j*18,180));addDataSlots(data);}
 private static Slot output(Container c,int index,int x,int y){return new Slot(c,index,x,y){@Override public boolean mayPlace(ItemStack s){return false;}};}
 public BlockPos position(){return pos;}public long power(){long value=0;for(int i=0;i<4;i++)value|=(long)(data.get(i)&65535)<<(i*16);return value;}public int consumption(){return data.get(4);}public float progress(){return Float.intBitsToFloat((data.get(5)&65535)|(data.get(6)&65535)<<16);}public boolean processing(){return data.get(7)!=0;}
 @Override public boolean stillValid(Player player){return machine.stillValid(player);}
 @Override public ItemStack quickMoveStack(Player player,int index){var slot=slots.get(index);if(!slot.hasItem())return ItemStack.EMPTY;var stack=slot.getItem();var copy=stack.copy();if(index<=10){if(!moveItemStackTo(stack,11,slots.size(),true))return ItemStack.EMPTY;}else{int first,last;var item=stack.getItem();if(item instanceof com.hbm.item.bedrockresource.RawBedrockOreItem){first=2;last=3;}else if(item instanceof com.hbm.machine.electricfurnace.FurnaceUpgradeItem||item instanceof com.hbm.machine.crystallizer.EffectUpgradeItem||item instanceof com.hbm.machine.centrifuge.OverdriveUpgradeItem){first=9;last=11;}else if(item instanceof FluidIdentifier){first=1;last=2;}else if(item instanceof HbmBattery||item instanceof CreativeBatteryItem){first=0;last=1;}else return ItemStack.EMPTY;if(!moveItemStackTo(stack,first,last,false))return ItemStack.EMPTY;}if(stack.isEmpty())slot.set(ItemStack.EMPTY);else slot.setChanged();return copy;}
}
